using System;using System.Text;using UnityEngine;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckMattressRacing {
public enum MattressPhase {Countdown,Race,Replay,RaceResult,Complete}
public sealed class MattressMatch:SportsEventSession {
 public MattressWorld world;public MattressRacer[] racers;public MattressCourse course;public SportsRallyViews views;public SportsMotionReplay replay;public TextMesh[] identities;public SportsRaceSeries series=new SportsRaceSeries();public MattressPhase Phase{get;private set;}public float RaceTime{get;private set;}public int Seed{get;private set;}
 float age;int focus;bool skip;readonly float[] times=new float[8],reaction=new float[8],noise=new float[8];readonly Vector2[] ai=new Vector2[8];readonly bool[] braceAI=new bool[8],air=new bool[8];readonly Vector3[] anchors=new Vector3[8];readonly StringBuilder text=new StringBuilder(1400);
 public override string Title=>"TRUCK MATTRESS RACING";public override int MinimumPlayers=>8;public override int MaximumPlayers=>8;public override int OptionCount=>6;public override int WeatherCount=>6;public override string OptionLabel=>"WEATHER: "+(option==0?"RANDOM":((SportsWeatherKind)(option-1)).ToString().ToUpperInvariant());public override bool MultiViewHUD=>views!=null&&views.Humans>0&&Phase!=MattressPhase.Replay;public override bool ReplayControls=>Phase==MattressPhase.Replay;
 public override string Help=>"BEDTIME ON THE FAST LANE\nEight real truck-and-mattress platforms, three downhill races. Two loose pillows match each player color, shift and fall independently, and reset each race. Gravity supplies propulsion: there are no powered tires hidden under your mattress. Each valid finisher earns 8/7/6/5/4/3/2/1 points. DNF earns zero. Total ties compare best finishing positions, then tied leaders race again. Exact simultaneous finishes share a place.\n\nLEAN WITH MOVEMENT\nLeft/right shifts weight and carves the fabric slide; forward/back shifts fore/aft balance and pitch. Momentum keeps moving while you spin. HOLD ACTION to brace: less rotation/bounce, more drag. The same controls, gravity, contact and recovery apply to every human and AI.\n\nFOLLOW THE FLAGS\nPass the eight checkpoint gates in order, then cross the finish. Seeded grass/mud, dips, ridges and small crests change the physical ride. Dodge exploding sheep, UTS runners, loose bins, barrels, cones, tires and rooted knockdown trees. Fallen trunks become nonblocking after six seconds. Everyone races the same generated course, and replays retain actual destruction poses. A sustained flip, fall or genuine stall returns you to the last passed safe checkpoint with a FIVE-SECOND stationary penalty; no forward skip. Three recoveries are available, then DNF. The generous100s race limit never invents a finisher. Ordinary slides and landings are not frozen.\n\nUP TO FOUR HUMANS\nUse independent keyboard clusters, controllers or exclusive shared sticks; AI fills eight. Names/colors and per-AI difficulty persist. Finished racers watch the active leader while every unfinished course and the shared weather continue. Pause/disconnect preserves the race. Reconnect/replacement requires neutral and fresh input. Actual-pose highlights offer angle/speed/rewind/skip and advance automatically for AI. Offline only.";
 public override string Header=>Title+" | "+(series.round>3?"TIEBREAK":"RACE "+series.round+" / 3")+" | "+course.weather.Description;
 public override string Status=>Phase==MattressPhase.Countdown?Mathf.CeilToInt(3-age).ToString():Phase==MattressPhase.Replay?"RECORDED PHYSICAL HIGHLIGHT":Phase==MattressPhase.Race?"LEAN TO CARVE | HOLD ACTION TO BRACE | "+RaceTime.ToString("F1")+"s":"PLACEMENT POINTS LOCKED";
 public override string Standings{get{text.Clear();for(int i=0;i<8;i++)text.Append(setup.players[i].name).Append("  ").Append(series.total[i]).Append(" PTS").Append(Phase==MattressPhase.Race?"  "+racers[i].Checkpoint+"/8":series.ranks[i]>0?"  #"+series.ranks[i]:"  DNF").Append(i==7?"":"\n");return text.ToString();}}
 public override string Results=>(series.winner>=0?setup.players[series.winner].name+" WINS THE SERIES\n\n":"TIED SERIES\n")+Standings;
 public override bool ValidateSources(out string reason){if(!base.ValidateSources(out reason))return false;int humans=0;for(int i=0;i<8;i++)if(setup.players[i].source!=BowlingSource.AI)humans++;if(humans>4){reason="At most four humans; AI fills the eight-racer field.";return false;}return true;}
 protected override void BeginGame(){Seed=UnityEngine.Random.Range(1,1000000);series.Reset(8,true);var colors=new Color[8];for(int i=0;i<8;i++)colors[i]=setup.players[i].color;replay.Colorize(colors);BeginRace();}
 void BeginRace(){series.BeginRound();RaceTime=age=0;Phase=MattressPhase.Countdown;skip=false;course.Generate(unchecked(Seed+series.round*997),option);world?.ResetWorld(unchecked(Seed+series.round*997));var random=new System.Random(Seed+series.round*19);for(int i=0;i<8;i++){times[i]=float.PositiveInfinity;reaction[i]=0;noise[i]=((float)random.NextDouble()*2-1)*(setup.players[i].difficulty==BowlingDifficulty.Easy?8:setup.players[i].difficulty==BowlingDifficulty.Normal?4:1.5f);racers[i].Prepare((series.eligible&(1<<i))!=0);}world?.ResetPillows();views.Restore();replay.ResetRecord();Gate();}
 Vector2 AI(int i){if(RaceTime<reaction[i])return ai[i];var r=racers[i];float level=(int)setup.players[i].difficulty;reaction[i]=RaceTime+Mathf.Lerp(.35f,.10f,level*.5f);float z=r.truck.body.position.z;var aim=course.Surface(new Vector3(course.Center(z+22)+noise[i]*Mathf.Sin(z*.021f+i),0,z+22));var forward=Vector3.ProjectOnPlane(r.transform.forward,Vector3.up);float angle=Vector3.SignedAngle(forward,Vector3.ProjectOnPlane(aim-r.truck.body.position,Vector3.up),Vector3.up);var vel=Vector3.ProjectOnPlane(r.truck.body.linearVelocity,Vector3.up);float slip=Vector3.SignedAngle(forward,vel.sqrMagnitude>.1f?vel:forward,Vector3.up);float steer=Mathf.Clamp(angle/28-slip*.008f,-1,1);float pitch=-Mathf.Clamp(r.truck.body.angularVelocity.x*.25f,-.7f,.7f);ai[i]=new Vector2(steer,pitch);braceAI[i]=Mathf.Abs(angle)>35||r.truck.body.angularVelocity.magnitude>2.5f;return ai[i];}
 protected override void Simulate(float dt){age+=dt;if(Phase==MattressPhase.Countdown){if(age>=3){Phase=MattressPhase.Race;age=0;foreach(var r in racers)r.Release();world?.ReleasePillows();replay.Record(0,series.eligible);feedback.Play(0,0,true);}return;}if(Phase==MattressPhase.Replay){if(replay.Step(dt)||skip&&replay.Age>1)EndReplay();return;}if(Phase==MattressPhase.RaceResult){if(age>=2){if(series.winner>=0){Phase=MattressPhase.Complete;EndMatch();}else BeginRace();}return;}if(Phase!=MattressPhase.Race)return;RaceTime+=dt;course.weather.Tick(RaceTime);int resolved=0,visible=0;float front=float.NegativeInfinity;for(int i=0;i<8;i++){bool bot=setup.players[i].source==BowlingSource.AI;var lean=bot?AI(i):commands[i];bool brace=bot?braceAI[i]:setup.players[i].released&&ActionHeld(i);racers[i].Step(lean,brace,dt);var r=racers[i];air[i]=!r.Grounded;if(r.Phase==MattressAttempt.Finished||r.Phase==MattressAttempt.DNF||r.Phase==MattressAttempt.Inactive)resolved++;if(r.Phase!=MattressAttempt.DNF&&r.Phase!=MattressAttempt.Inactive){visible|=1<<i;if(r.Phase==MattressAttempt.Racing&&r.truck.body.position.z>front){front=r.truck.body.position.z;focus=i;}}}replay.Record(RaceTime,visible|(world!=null?1<<8:0));if(RaceTime>=100){foreach(var r in racers)if(r.Phase!=MattressAttempt.Finished)r.Fail();resolved=8;}if(resolved==8)ResolveRace();}
 void ResolveRace(){for(int i=0;i<8;i++)times[i]=racers[i].FinishTime;if(!series.Resolve(times))return;int visible=0;for(int i=0;i<8;i++)if(racers[i].Phase==MattressAttempt.Finished)visible|=1<<i;replay.Record(RaceTime+.06f,visible|(world!=null?1<<8:0));world?.Hide();foreach(var r in racers){r.Stop();r.truck.visuals.gameObject.SetActive(false);r.cushion.gameObject.SetActive(false);}Phase=MattressPhase.Replay;age=0;float last=0;for(int i=0;i<8;i++)if(!float.IsInfinity(times[i]))last=Mathf.Max(last,times[i]);replay.Begin(Mathf.Max(0,last-5),Mathf.Min(RaceTime,last+1));views.Replay=false;Gate();Debug.Log("MATTRESS_RACE_LOCK race="+series.round+" ranks="+string.Join(",",series.ranks)+" total="+string.Join(",",series.total));}
 void EndReplay(){replay.End();views.Restore();Phase=MattressPhase.RaceResult;age=0;}
 public void Arrived(MattressRacer r){feedback.Play(5,0,true);Pulse(r.slot,.18f,.12f);}public void Recovered(MattressRacer r){feedback.Play(2,0,true);Pulse(r.slot,.2f,.1f);}public void Impact(int slot,float speed){feedback.Play(speed>6?7:1,speed);if(speed>6)Pulse(slot,Mathf.Clamp01(speed/25)*.25f,.08f);}
 public override string ViewText(int view){int i=views.owners[view];var r=racers[i];return "<color=#"+ColorUtility.ToHtmlStringRGB(setup.players[i].color)+">"+setup.players[i].name+"</color> | "+series.total[i]+" PTS\n"+(series.round>3?"TIEBREAK":"RACE "+series.round+"/3")+" | "+r.Checkpoint+"/8 FLAGS\n"+(r.Phase==MattressAttempt.Recovery?"RECOVERY +5s | "+r.RecoveryRemaining.ToString("F1"):r.Phase==MattressAttempt.Finished?"FINISHED | "+r.FinishTime.ToString("F2")+"s":r.Phase==MattressAttempt.DNF||r.Phase==MattressAttempt.Inactive?"OUT | WATCHING LEADER":r.Bracing?"BRACING | MORE DRAG":"LEAN | HOLD ACTION TO BRACE");}
 protected override void Present(float dt){if(views==null||racers==null)return;if(Phase==MattressPhase.Replay&&replay.Playing){views.ReplayView(replay.Position(focus),replay.Angle);return;}for(int i=0;i<8;i++){anchors[i]=racers[i].Phase==MattressAttempt.Finished?racers[i].FinishOrigin:racers[i].truck.body.position;identities[i].transform.position=racers[i].truck.body.position+Vector3.up*3;identities[i].text=setup.players[i].name;identities[i].color=setup.players[i].color;}views.Focus=focus;views.Follow(dt,air,anchors);for(int v=0;v<views.Humans;v++){var r=racers[views.owners[v]];if(Phase==MattressPhase.Race&&(r.Phase==MattressAttempt.Finished||r.Phase==MattressAttempt.DNF||r.Phase==MattressAttempt.Inactive))views.views[v].Pose(anchors[focus]+Vector3.up,new Vector3(12,12,-24),68,true);}}
 public override void ExtraAction(string key){if(!ReplayControls)return;if(key=="replayangle")replay.Angle=(replay.Angle+1)%3;else if(key=="replayspeed")replay.Speed=replay.Speed<.5f?1:replay.Speed<1.1f?2:replay.Speed<2.1f?4:.25f;else if(key=="replayrewind")replay.Seek(Mathf.Max(0,replay.Cursor-3));else if(key=="replayskip")skip=true;ConsumeActions();}
 protected override void StopGame(){replay?.End();world?.Freeze();if(racers!=null)foreach(var r in racers)r.Stop();}protected override void SetPaused(bool paused)=>course?.weather?.Pause(paused);protected override void StopSounds(){if(racers!=null)foreach(var r in racers)r.truck.StopSound();}
}
}
